**track.js:**
```javascript
const { record } = require('./event');
exports.track = record;
```
This is an alias to the `record` function from event.js.

**event.js:**
```javascript
const { table } = require('../shared/db');
const { shortId } = require('../shared/ids');
exports.record = ({ userId, kind, props }) => { 
  const id = shortId('e'); 
  table('events').set(id, { id, userId, kind, props: props||{}, ts: new Date().toISOString() }); 
  return id; 
};
```

**Module Name:** `analytics/event` or `analytics/track` (aliased)
**Function Signature:** `record({ userId, kind, props })`
- Parameters:
  - `userId`: User ID associated with the event
  - `kind`: Type/name of the event
  - `props`: Additional properties (optional, defaults to empty object)
- Returns: The ID of the recorded event

**aggregate.js:**
```javascript
const { allEvents } = require('./repository');
exports.countByKind = () => { 
  const out = {}; 
  for (const e of allEvents()) 
    out[e.kind] = (out[e.kind]||0)+1; 
  return out; 
};
```

**session-track.js:**
```javascript
const { table } = require('../shared/db');
const { shortId } = require('../shared/ids');
exports.startSession = ({ userId }) => { 
  const id = shortId('asess'); 
  table('asessions').set(id, { id, userId, startedAt: Date.now(), endedAt: null }); 
  return id; 
};
exports.endSession = ({ id }) => { 
  const s = table('asessions').get(id); 
  if (!s) return false; 
  s.endedAt = Date.now(); 
  return true; 
};
```

**export-events.js:**
```javascript
const { allEvents } = require('./repository');
exports.exportAll = () => allEvents()
  .map(e => `${e.id},${e.kind},${e.userId},${e.ts}`)
  .join('\n');
```

**query.js:**
```javascript
const { allEvents } = require('./repository');
exports.byKind = kind => allEvents().filter(e => e.kind === kind);
exports.byUser = uid => allEvents().filter(e => e.userId === uid);
```

**repository.js:**
```javascript
const { table } = require('../shared/db');
exports.allEvents = () => Array.from(table('events').values());
exports.allSessions = () => Array.from(table('asessions').values());
```

**funnel.js:**
```javascript
const { byUser } = require('./query');
exports.funnel = ({ userId, steps }) => { 
  const evs = byUser(userId); 
  return steps.map(s => evs.some(e => e.kind === s)); 
};
```

**dashboard.js:**
```javascript
const { table } = require('../shared/db');
exports.summary = () => ({ 
  users: table('users').size, 
  orders: table('orders').size, 
  events: table('events').size 
});
```

