### 4. **src/users/** - Files and Content

**List of files:**
- profile.js
- export.js
- preferences.js
- user.js
- delete.js
- list.js
- audit.js
- repository.js
- suspend.js
- search.js
- settings.js

**Key Files:**

**repository.js:**
```javascript
const { table } = require('../shared/db');
function users() { return table('users'); }
exports.findByEmail = e => typeof e === 'string' ? users().get(e.toLowerCase()) || null : null;
exports.findById = id => { 
  for (const u of users().values()) 
    if (u.id === id) 
      return u; 
  return null; 
};
exports.save = u => { users().set(u.email.toLowerCase(), u); return u; };
exports.update = (id, patch) => { 
  const u = exports.findById(id); 
  if (!u) return null; 
  const next = { ...u, ...patch }; 
  users().set(next.email.toLowerCase(), next); 
  return next; 
};
exports.list = () => Array.from(users().values());
```

**Module Name:** `users/repository`
**Function to Look Up User by ID:** `findById(id)`
- Parameter: `id` - User ID
- Returns: User object or null if not found
- **Note:** Iterates through all users and finds the one matching the ID

**user.js:**
```javascript
const { isEmail } = require('../shared/validation');
function makeUser({ id, email, passwordHash, createdAt, currency }) {
  if (!id || !isEmail(email) || !passwordHash) throw new Error('invalid user');
  return { 
    id, 
    email: email.toLowerCase(), 
    passwordHash, 
    createdAt: createdAt || new Date().toISOString(), 
    currency: currency || 'USD' 
  };
}
module.exports = { makeUser };
```

**profile.js:**
```javascript
const { findById, update } = require('./repository');
exports.getProfile = ({ userId }) => { 
  const u = findById(userId); 
  return u ? { ok: true, profile: { id: u.id, email: u.email, name: u.name || null } } : { ok: false }; 
};
exports.updateProfile = ({ userId, patch }) => { 
  const u = update(userId, patch || {}); 
  return u ? { ok: true, profile: u } : { ok: false }; 
};
```

**preferences.js:**
```javascript
const { update, findById } = require('./repository');
exports.setPreference = ({ userId, key, value }) => { 
  const u = findById(userId); 
  if (!u) return { ok: false }; 
  const prefs = { ...(u.preferences||{}), [key]: value }; 
  update(userId, { preferences: prefs }); 
  return { ok: true }; 
};
```

---

### 5. **test/billing.test.js**

Full content:
```javascript
const assert = require('assert');
const { run } = require('./_runner');
const { clearAll } = require('../src/shared/db');
const { signup } = require('../src/auth/signup');
const { subscribe } = require('../src/billing/subscribe');
const { generateInvoice } = require('../src/billing/invoice');

run('subscribe', () => { 
  clearAll(); 
  const u = signup({ email:'a@b.co', password:'password1' }).user; 
  const r = subscribe({ userId: u.id, planId: 'pro' }); 
  assert.strictEqual(r.ok, true); 
});

run('invoice', () => { 
  clearAll(); 
  const u = signup({ email:'a@b.co', password:'password1' }).user; 
  const s = subscribe({ userId: u.id, planId: 'pro' }).subscription; 
  const inv = generateInvoice({ subscriptionId: s.id }); 
  assert.ok(inv.amount > 0); 
});

if (process.exitCode) process.exit(process.exitCode);
```

**Test Structure:**
- Uses a custom `run()` test helper from `./_runner` module
- Uses `assert` module for assertions
- Tests clear the database with `clearAll()` before each test
- Test 1 ('subscribe'): Creates a user via signup, then subscribes to 'pro' plan, asserts success (ok: true)
- Test 2 ('invoice'): Creates a user, subscribes, then generates an invoice and asserts the amount is greater than 0
- Process exit handling at the end

